import getpass
from django.contrib.auth import get_user_model
from django.core.management.base import BaseCommand, CommandError
from django.core.exceptions import ValidationError
from django.contrib.auth.password_validation import validate_password
from dashboard.models import Organization

class Command(BaseCommand):
    help = 'Create a new superuser with an organization'

    def add_arguments(self, parser):
        parser.add_argument('--username', required=True, help='Specifies the username for the superuser.')
        parser.add_argument('--email', required=True, help='Specifies the email for the superuser.')
        parser.add_argument('--organization', required=True, help='Specifies the organization for the superuser.')

    def handle(self, *args, **options):
        User = get_user_model()
        username = options['username']
        email = options['email']
        organization_name = options['organization']

        # Check if the user already exists
        if User.objects.filter(username=username).exists():
            raise CommandError(f'User "{username}" already exists.')

        # Get or create the organization
        try:
            organization = Organization.objects.get(name=organization_name)
        except Organization.DoesNotExist:
            raise CommandError(f'Organization "{organization_name}" does not exist.')

        # Prompt for a password
        password = getpass.getpass()
        password2 = getpass.getpass('Password (again): ')
        if password != password2:
            raise CommandError("Error: Your passwords didn't match.")
        if password.strip() == '':
            raise CommandError("Error: Blank passwords aren't allowed.")
        try:
            validate_password(password)
        except ValidationError as e:
            raise CommandError('; '.join(e.messages))

        # Create the superuser
        user = User.objects.create_superuser(
            username=username,
            email=email,
            password=password,
            organization=organization  # Assign the organization here
        )
        user.organization = organization
        user.save()

        self.stdout.write(self.style.SUCCESS(f'Successfully created new superuser "{username}" with organization "{organization_name}".'))
